        }
    }

    @Override
    public Price price(Booking b, BigDecimal nightsSum) {
        return new Price(PRICES.get(b.roomType()), Money.ZERO);
    }

    @Override
    public BigDecimal refund(BigDecimal amountPaid) {
        return Money.percent(amountPaid, 50);
    }
}
